package com.mallcloud.search;
import com.mallcloud.api.client.ProductClient; import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.cloud.client.discovery.EnableDiscoveryClient; import org.springframework.cloud.openfeign.EnableFeignClients; import org.springframework.scheduling.annotation.EnableScheduling;
@EnableScheduling @EnableDiscoveryClient @EnableFeignClients(clients=ProductClient.class) @SpringBootApplication(scanBasePackages="com.mallcloud") public class SearchApplication {public static void main(String[] args){SpringApplication.run(SearchApplication.class,args);}}
